## ----cate-net, out.width="70%", fig.align="center", fig.pos="!ht", fig.cap = "Estimating CATE Using Deep Neural Networks"----
knitr::include_graphics(normalizePath("figures/CATE_network.png"))


## ----load_package, results='hide', message=FALSE, warning=FALSE---------------
library(DeepLearningCausal)
library(SuperLearner)
python_ready()


## ----import_exp, echo = TRUE--------------------------------------------------
data("exp_data_full") 
str(exp_data_full) 


## ----import_pop, echo = TRUE--------------------------------------------------
data("pop_data_full")
str(pop_data_full)


## ----response, echo = TRUE----------------------------------------------------
response_formula <- support_war ~ age + female + education + income + employed + 
                                  job_loss + hindu + political_ideology


## ----samples, results = 'hide', message=FALSE, warning=FALSE------------------
set.seed(1234)
exp_split <- rsample::initial_split(exp_data_full,)
train_data <- rsample::training(exp_split)
test_data <- rsample::testing(exp_split)

slearner_deep <- metalearner_deeplearning(cov.formula = response_formula, 
                                          train.data = train_data,
                                          test.data = test_data,
                                          treat.var = "strong_leader", meta.learner.type = "S.Learner",
                                          algorithm = "adam", hidden.layer = c(4,2), hidden_activation = "relu",
                                          output_activation = "sigmoid", output_units = 1,
                                          loss = "binary_crossentropy", metrics = "accuracy", epoch = 100,
                                          batch_size = 32, validation_split = 0.2, dropout_rate = 0.1, patience = 20, 
                                          conformal = TRUE,
                                          alpha = 0.1,
                                          calib_frac = 0.5, prob_bound = TRUE,
                                          verbose = 1, seed = 1234)


## ----sltrace, echo = TRUE, out.width="70%", fig.align="center", fig.pos="!ht" , fig.cap="Accuracy Plot and Trace Plot of the Loss Function for the S-Learner"----
plot(slearner_deep$ml_model_history[[1]])


## ----tlearner, results='hide', message=FALSE, warning=FALSE-------------------
tlearner_deep <- metalearner_deeplearning(cov.formula = response_formula, 
                                          train.data = train_data,
                                          test.data = test_data,
                                          treat.var = "strong_leader", 
                                          meta.learner.type = "T.Learner",
                                          algorithm = "adam", hidden.layer = c(4,2), hidden_activation = "relu",
                                          output_activation = "sigmoid", output_units = 1,
                                          loss = "binary_crossentropy", metrics = "accuracy", epoch = 100,
                                          batch_size = 32, validation_split = 0.2, dropout_rate = 0.1, patience = 20, 
                                          conformal = TRUE,
                                          alpha = 0.1,
                                          calib_frac = 0.5, prob_bound = TRUE,
                                          verbose = 1, seed = 1234)


## ----print_st-----------------------------------------------------------------
print(slearner_deep)
print(tlearner_deep)


